function endGame(){running=false;ui.overline.textContent='SHIFT TERMINATED // SECTOR LOST';ui.title.innerHTML='MEAT<br><em>WINS.</em>';ui.description.textContent=`You survived ${Math.max(0,wave-1)} wave${wave===2?'':'s'} and scrapped ${kills} hostiles. The foundry will remember.`;ui.start.textContent='RUN IT BACK';ui.footnote.textContent=`FINAL SCRAP: ${score} // HOSTILES CLEARED: ${kills}`;ui.overlay.classList.remove('hidden')}
