function announce(title,sub,d=2){ui.bannerTitle.textContent=title;ui.bannerSub.textContent=sub;ui.banner.classList.add('show');bannerTimer=d}
function spawnEnemy(){const edge=Math.floor(Math.random()*4),pad=28;let x,y;if(edge===0){x=rand(45,W-45);y=pad}else if(edge===1){x=W-pad;y=rand(70,H-40)}else if(edge===2){x=rand(45,W-45);y=H-pad}else{x=pad;y=rand(70,H-40)}let heavy=wave>=3&&Math.random()<Math.min(.3,.08+wave*.018),spitter=wave>=2&&!heavy&&Math.random()<.25;enemies.push({x,y,r:heavy?21:spitter?14:16,hp:heavy?5:spitter?2:3,max:heavy?5:spitter?2:3,speed:heavy?31:spitter?39:48,kind:heavy?'brute':spitter?'spitter':'crawler',hit:0,attack:rand(.4,1.3),angle:0})}
