function shoot(){if(player.reload>0||player.fire>0)return;if(player.ammo<=0){reloadGun();return}let target=null,best=Infinity;for(const e of enemies){let d=Math.hypot(e.x-player.x,e.y-player.y);if(d<best){best=d;target=e}}let angle=mouse.down?Math.atan2(mouse.y-player.y,mouse.x-player.x):(target?Math.atan2(target.y-player.y,target.x-player.x):player.angle);player.angle=angle;player.ammo--;player.fire=.31;let spread=rand(-.045,.045);bullets.push({x:player.x+Math.cos(angle)*18,y:player.y+Math.sin(angle)*18,vx:Math.cos(angle+spread)*530,vy:Math.sin(angle+spread)*530,life:.72,damage:1});shake=2.2;burst(player.x+Math.cos(angle)*18,player.y+Math.sin(angle)*18,'#f3d37a',3,55)}
function reloadGun(){if(player.reload<=0&&player.ammo<player.maxAmmo){player.reload=1.15;ui.reload.textContent='RELOADING…'}}
function dodge(){if(player.roll<=0){let dx=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+touch.x,dy=(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0)+touch.y,len=Math.hypot(dx,dy);if(len<.1){dx=Math.cos(player.angle);dy=Math.sin(player.angle)}else{dx/=len;dy/=len}player.roll=.24;player.inv=.42;player.vx=dx*580;player.vy=dy*580;burst(player.x,player.y,'#d5f451',8,65)}}
function update(dt){elapsed+=dt;player.fire=Math.max(0,player.fire-dt);player.inv=Math.max(0,player.inv-dt);player.roll=Math.max(0,player.roll-dt);if(player.reload>0){player.reload-=dt;if(player.reload<=0){player.ammo=player.maxAmmo;ui.reload.textContent=''}}if(bannerTimer>0){bannerTimer-=dt;if(bannerTimer<=0)ui.banner.classList.remove('show')}
let mx=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+touch.x,my=(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0)+touch.y,len=Math.hypot(mx,my);if(len>1){mx/=len;my/=len}if(player.roll>0){player.x+=player.vx*dt;player.y+=player.vy*dt;player.vx*=Math.pow(.025,dt);player.vy*=Math.pow(.025,dt)}else{player.x+=mx*170*dt;player.y+=my*170*dt}player.x=clamp(player.x,30,W-30);player.y=clamp(player.y,90,H-35);if(mx||my){if(!mouse.down&&!touch.fire)player.angle=Math.atan2(my,mx)}
if(mouse.down||touch.fire||keys.Space)shoot();
