for(let i=enemies.length-1;i>=0;i--){let e=enemies[i],dx=player.x-e.x,dy=player.y-e.y,d=Math.hypot(dx,dy)||1;e.angle=Math.atan2(dy,dx);e.hit=Math.max(0,e.hit-dt);e.attack-=dt;if(e.kind==='spitter'){if(d>195){e.x+=dx/d*e.speed*dt;e.y+=dy/d*e.speed*dt}else if(d<145){e.x-=dx/d*e.speed*.65*dt;e.y-=dy/d*e.speed*.65*dt}if(e.attack<=0&&d<320){enemyShots.push({x:e.x,y:e.y,vx:dx/d*190,vy:dy/d*190,life:2});e.attack=rand(1.4,2.1)}}else if(d>e.r+player.r+4){e.x+=dx/d*e.speed*dt;e.y+=dy/d*e.speed*dt}else{e.attack-=dt;if(e.attack<=0&&player.inv<=0){player.hp-=e.kind==='brute'?18:10;e.attack=e.kind==='brute'?1.1:.8;shake=7;burst(player.x,player.y,'#d84c32',7,100)}}}
